# HarvestForge-X | High-Throughput Farming and Premium-Market Strategy
#
# HarvestForge-X is a production-focused strategy built around rapid livestock expansion, efficient field utilisation, and early access to high-value market opportunities. Its core configuration targets 8 cattle and 4 sheep, while prioritising premium returns from melon, strawberry, and wool.
#
# The strategy was independently reconstructed by comparing three publicly accessible reference runs associated with a previously high-performing submission. The examined runs were 92165990, 92185587, and 92223213. Despite being separate traces, they displayed an almost identical production sequence, while their market decisions agreed at approximately 99.91% of decision points.
#
# This consistency made it possible to derive a deterministic baseline rather than relying on a single replay. At each stage, the most frequently observed action was selected and incorporated into the executable strategy.
#
# Experimental Performance
#
# The reconstructed policy was evaluated through local paired simulations using 30 independent seeds and both possible player orders.
#
# The candidate achieved:
#
# - 60 wins out of 60 games
# - 30/30 positive paired comparisons
# - Successful completion of additional two-player regression tests against established public reference agents
#
# These numbers describe local simulation results only and should not be interpreted as official competition scores.
#
# Strategy Architecture
#
# The main idea is to accelerate the farm's transition from its initial state into a high-output production system.
#
# The strategy progressively:
#
# - Unlocks and utilises three additional farm areas.
# - Establishes the livestock base early, reaching four sheep before expanding toward eight cattle.
# - Maintains continuous crop production through a rotation centred on grain and premium fruits.
# - Coordinates labour allocation with feeding, animal maintenance, planting, harvesting, and fertilisation.
# - Converts accumulated production into repeated premium-market sales rather than waiting for a single late-game transaction.
#
# This creates a production loop in which expansion, resource generation, and market activity reinforce one another.
#
# Execution Layer
#
# HarvestForge-X is not limited to replaying a fixed sequence of actions.
#
# Before executing an operation, the controller checks the current number of available workers and adapts the action queue accordingly. This prevents the strategy from depending on an exact worker count that may differ from the reference trace.
#
# The execution layer also contains a recovery mechanism for blocked field operations. If an obstruction appears where a planned planting or pasture-construction action is scheduled, the controller resolves the blockage first and then resumes the intended sequence.
#
# As a result, the strategy preserves the high-output structure extracted from the reference runs while remaining capable of recovering from small deviations in the live game state.
#
# Core Production Cycle
#
# The resulting policy can therefore be viewed as four connected phases:
#
# Expansion → Production → Livestock Growth → Premium Sales
#
# Early actions concentrate on unlocking productive capacity and establishing the required workforce. The middle phase increases livestock and crop throughput, while the final stage repeatedly converts the accumulated resources into higher-value market opportunities.
#
# The objective is not simply to reproduce a successful replay, but to preserve its underlying decision pattern while making the execution more robust to variations in game state.
#
